package glitch

import data.glitch_lib
import strings

# Define keyword names for binding attributes (lowercase)
keyword_names := {"listen_address", "bind_address", "host", "ip_address", "address", "server_bind", "bind_ip", "external_ip", "public_ip", "host_ip", "ip"}

# Define unrestricted IP values
unrestricted_ips := {"0.0.0.0", "::", "all", "any"}

# Helper function to get string value from an expression
get_string_value(expr) = str {
    expr.ir_type == "String"
    str := expr.value
} else {
    expr.ir_type == "VariableReference"
    # Remove leading colon if present (for symbols in Ruby/Chef)
    str := strings.trim_prefix(expr.value, ":")
} else {
    # For other types, return empty string (won't match)
    str := ""
}

# Helper rule to check if a string (context) contains any keyword (case-insensitive)
contains_keyword(context, keywords) {
    kw := keywords[_]
    regex.match(sprintf("(?i).*%s.*", [kw]), context)
}

# Recursive rule to check for unrestricted IP binding
check_binding(node, context) {
    node.ir_type == "String"
    unrestricted_ips[node.value]
    contains_keyword(lower(context), keyword_names)
}

check_binding(node, context) {
    node.ir_type == "Hash"
    pair := node.value[_]
    key_str := get_string_value(pair.key)
    check_binding(pair.value, key_str)
}

check_binding(node, context) {
    node.ir_type == "Array"
    elem := node.value[_]
    check_binding(elem, context)
}

# Main rule for variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]
    check_binding(var.value, var.name)

    result := {
        "type": "sec_invalid_bind",
        "element": var,
        "path": parent.path,
        "description": "Binding to an unrestricted IP address - Services should not bind to 0.0.0.0 or equivalent addresses. (CWE-1327)"
    }
}

# Main rule for attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    check_binding(attr.value, attr.name)

    result := {
        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
        "description": "Binding to an unrestricted IP address - Services should not bind to 0.0.0.0 or equivalent addresses. (CWE-1327)"
    }
}

